/* From Uiverse.io by vikas7754  - Tags: neumorphism, tooltip, 3d, dark, modern */
.__UIV_SCOPE__ .tooltip-container {
  position: relative;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 17px;
  border-radius: 10px;
}

.__UIV_SCOPE__ .tooltip {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  padding: 10px;
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s;
  border-radius: 15px;
  box-shadow: inset 5px 5px 5px rgba(0, 0, 0, 0.2),
    inset -5px -5px 15px rgba(255, 255, 255, 0.1),
    5px 5px 15px rgba(0, 0, 0, 0.3), -5px -5px 15px rgba(255, 255, 255, 0.1);
}

.__UIV_SCOPE__ .profile {
  background: #2a2b2f;
  border-radius: 10px 15px;
  padding: 10px;
  border: 1px solid rgba(11, 63, 95, 1);
}

.__UIV_SCOPE__ .tooltip-container:hover .tooltip {
  top: -150px;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.__UIV_SCOPE__ .icon {
  text-decoration: none;
  color: #fff;
  display: block;
  position: relative;
}
.__UIV_SCOPE__ .layer {
  width: 55px;
  height: 55px;
  transition: transform 0.3s;
}
.__UIV_SCOPE__ .icon:hover .layer {
  transform: rotate(-35deg) skew(20deg);
}
.__UIV_SCOPE__ .layer span {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  border: 1px solid #fff;
  border-radius: 5px;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .layer span,
.__UIV_SCOPE__ .text {
  color: #1da1f2;
  border-color: #1da1f2;
}

.__UIV_SCOPE__ .icon:hover.layer span {
  box-shadow: -1px 1px 3px #1da1f2;
}
.__UIV_SCOPE__ .icon .text {
  position: absolute;
  left: 50%;
  bottom: -5px;
  opacity: 0;
  font-weight: 500;
  transform: translateX(-50%);
  transition: bottom 0.3s ease, opacity 0.3s ease;
}
.__UIV_SCOPE__ .icon:hover .text {
  bottom: -35px;
  opacity: 1;
}

.__UIV_SCOPE__ .icon:hover .layer span:nth-child(1) {
  opacity: 0.2;
}
.__UIV_SCOPE__ .icon:hover .layer span:nth-child(2) {
  opacity: 0.4;
  transform: translate(5px, -5px);
}
.__UIV_SCOPE__ .icon:hover .layer span:nth-child(3) {
  opacity: 0.6;
  transform: translate(10px, -10px);
}
.__UIV_SCOPE__ .icon:hover .layer span:nth-child(4) {
  opacity: 0.8;
  transform: translate(15px, -15px);
}
.__UIV_SCOPE__ .icon:hover .layer span:nth-child(5) {
  opacity: 1;
  transform: translate(20px, -20px);
}

.__UIV_SCOPE__ .layer span.fab {
  font-size: 30px;
  line-height: 64px;
  text-align: center;
  fill: #1da1f2;
  background: #000;
}
.__UIV_SCOPE__ .user {
  display: flex;
  gap: 10px;
}
.__UIV_SCOPE__ .img {
  width: 50px;
  height: 50px;
  font-size: 25px;
  font-weight: 700;
  border: 1px solid #1da1f2;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
}
.__UIV_SCOPE__ .name {
  font-size: 17px;
  font-weight: 700;
  color: #1da1f2;
}
.__UIV_SCOPE__ .details {
  display: flex;
  flex-direction: column;
  gap: 0;
  color: #fff;
}
.__UIV_SCOPE__ .about {
  color: #ccc;
  padding-top: 5px;
}
